const moduleLessons=[['Business Analysis là gì?','Vai trò BA trong vòng đời dự án','Các nhóm stakeholder','Tư duy giải quyết vấn đề','Phân loại yêu cầu','Đo lường giá trị kinh doanh'],['Lập kế hoạch khai thác yêu cầu','Kỹ thuật phỏng vấn','Workshop & brainstorming','Stakeholder Analysis & Mapping','Quan sát và phân tích tài liệu','Xác nhận kết quả khai thác'],['Vòng đời của yêu cầu','Ưu tiên với MoSCoW','Truy vết yêu cầu với RTM','Quản lý thay đổi yêu cầu','Phê duyệt và baseline','Giải quyết yêu cầu mâu thuẫn'],['Đọc hiểu lưu đồ quy trình','BPMN: Event, Task & Gateway','Mô hình As-is và To-be','Swimlane & trách nhiệm','Xử lý ngoại lệ trong quy trình','Thực hành mô hình hóa'],['Từ nhu cầu đến giải pháp','User story & acceptance criteria','Use case & kịch bản ngoại lệ','Phân tích business rule','Đánh giá phương án giải pháp','Yêu cầu phi chức năng'],['Tư duy dữ liệu cho BA','SQL: SELECT và WHERE','JOIN & quan hệ dữ liệu','REST API & HTTP cơ bản','Đọc tài liệu API','Chỉ số và chất lượng dữ liệu'],['Agile mindset','Vai trò trong Scrum','Product Backlog & refinement','Sprint Planning & Sprint Goal','Kanban & giới hạn WIP','Retrospective hiệu quả'],['Nghiên cứu người dùng','Persona & hành trình khách hàng','Problem statement','Wireframe & prototype','Kiểm thử khả dụng','Ưu tiên theo giá trị sản phẩm'],['Vai trò BA trong kiểm thử','Thiết kế test scenario','Acceptance criteria đến test case','Lập kế hoạch UAT','Phân loại và xử lý lỗi','Nghiệm thu giải pháp'],['Giao tiếp với stakeholder','Kỹ thuật trình bày giải pháp','Xử lý xung đột','Chuẩn bị phỏng vấn BA','Trả lời câu hỏi tình huống','Trình bày case study']];
function currentLessons(){return moduleLessons[trackId]||lessonNames}
let libraryFilter='all',libraryView='grid';
function lessonStatus(t,l){
  if(state.done.includes(key(t,l))) return 'done';
  if(typeof VyProfileManager!=='undefined'){
    var pData=VyProfileManager.getProfileData();
    if(pData&&pData.lastActivity&&pData.lastActivity.type==='lesson'&&pData.lastActivity.data&&pData.lastActivity.data.trackId===t&&pData.lastActivity.data.lessonId===l){
      return 'learning';
    }
  }
  return 'new';
}
function libraryPage(){
 let total=moduleLessons.reduce((n,l)=>n+l.length,0),done=moduleLessons.reduce((n,ls,t)=>n+ls.filter((_,l)=>lessonStatus(t,l)==='done').length,0),percent=Math.round(done/total*100);
 let modules=tracks.map((t,i)=>({t,i})).filter(({i})=>libraryFilter==='all'||(libraryFilter==='basic'?i<4:libraryFilter==='advanced'?i>=4:libraryFilter==='learning'?moduleLessons[i].some((_,l)=>lessonStatus(i,l)==='learning'):moduleLessons[i].every((_,l)=>lessonStatus(i,l)==='new')));
 return `<div class="lib-page">${heading('Thư viện bài học','Khám phá kiến thức theo từng miền chuyên môn')}<div class="lib-toolbar"><div class="lib-filters" role="group" aria-label="Lọc bài học">${[['all','Tất cả'],['basic','Cơ bản'],['advanced','Nâng cao'],['learning','Đang học'],['new','Chưa học']].map(([v,n])=>`<button data-lib-filter="${v}" aria-pressed="${v===libraryFilter}" class="${v===libraryFilter?'selected':''}">${n}</button>`).join('')}</div><div class="lib-views" role="group" aria-label="Chế độ xem"><button data-lib-view="grid" aria-label="Xem dạng lưới" aria-pressed="${libraryView==='grid'}" class="${libraryView==='grid'?'selected':''}">${uiIcon('grid')}</button><button data-lib-view="list" aria-label="Xem dạng danh sách" aria-pressed="${libraryView==='list'}" class="${libraryView==='list'?'selected':''}">${uiIcon('list')}</button></div></div><div class="lib-progress"><span class="lib-progress-icon">${uiIcon('book')}</span><div><b>Hành trình kiến thức của bạn</b><span>${done}/${total} bài mẫu đã hoàn thành</span></div><div class="lib-progress-meter">${bar(percent)}<b>${percent}%</b></div><button data-nav="Case study">Luyện case study</button></div><div class="lib-section-title"><span>${modules.length} miền kiến thức</span><span>Học theo nhịp độ của bạn</span></div><div class="module-grid ${libraryView==='list'?'module-list':''}">${modules.map(({t,i})=>{let count=moduleLessons[i].filter((_,l)=>lessonStatus(i,l)==='done').length,ongoing=moduleLessons[i].some((_,l)=>lessonStatus(i,l)==='learning'),colors=['#7763d8','#4d8bdd','#439e82','#d78e48','#b477ba','#578fa8','#8270c9','#b78b39','#419b95','#7885bd'];return `<article class="module-card" style="--module-accent:${colors[i]}"><div class="module-head"><div class="module-title-row"><span class="module-icon">${uiIcon(['target','users','file','flow','spark','data','repeat','grid','check','chat'][i])}</span><span class="module-level">${i<4?'Cơ bản':'Nâng cao'}</span></div><h2>${t[0]}</h2><div class="module-meta"><span>6 bài học · 78 phút</span><span>${count}/6 hoàn thành</span></div>${bar(Math.round(count/6*100),colors[i])}</div><div class="module-lessons">${moduleLessons[i].slice(0,4).map((n,l)=>{let status=lessonStatus(i,l);return `<button class="module-lesson ${status}" data-lesson="${i},${l}"><span class="lesson-state" aria-label="${status==='done'?'Đã học':status==='learning'?'Đang học':'Chưa học'}">${status==='done'?uiIcon('check'):status==='learning'?'<span class="state-dot"></span>':String(l+1).padStart(2,'0')}</span><span class="lesson-name">${n}</span><svg class="lesson-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></button>`}).join('')}</div><footer><span>${ongoing?'Đang học':'Còn 2 bài trong module'}</span><button ${ongoing?`data-lesson="${i},3"`:`data-track="${i}"`}>${ongoing?'Tiếp tục học':'Xem tất cả bài học'}<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></button></footer></article>`}).join('')||'<div class="empty">Chưa có module phù hợp với bộ lọc này.</div>'}</div><p class="lib-note">Nội dung bài mẫu · Hoàn thành bài học để cập nhật tiến độ trên thiết bị này.</p></div>`;
}
function setupMenu(){
 let stored;try{stored=localStorage.getItem('ba-menu-collapsed')==='true'}catch{}document.body.classList.toggle('menu-collapsed',!!stored);
 const btn=document.createElement('button');btn.id='menu-toggle';btn.className='menu-toggle';btn.setAttribute('aria-label','Đóng hoặc mở menu');btn.setAttribute('aria-controls','sidebar');btn.innerHTML='<svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="3"/><path d="M9 4v16M13 9h4M13 13h4"/></svg>';document.querySelector('header').prepend(btn);
 const closeButton=document.createElement("button");closeButton.id="sidebar-close";closeButton.setAttribute("aria-label","Đóng menu");closeButton.innerHTML="×";document.querySelector("#sidebar").prepend(closeButton);const overlay=document.createElement('button');overlay.id='menu-overlay';overlay.setAttribute('aria-label','Đóng menu');overlay.tabIndex=-1;document.body.append(overlay);
 const close=()=>{document.body.classList.remove('menu-open');btn.setAttribute('aria-expanded',String(innerWidth>900&&!document.body.classList.contains('menu-collapsed')))};
 btn.addEventListener('click',()=>{if(innerWidth<=900){let open=document.body.classList.toggle('menu-open');btn.setAttribute('aria-expanded',String(open));if(open)document.querySelector('#sidebar [data-nav]').focus()}else{document.body.classList.toggle('menu-collapsed');localStorage.setItem('ba-menu-collapsed',String(document.body.classList.contains('menu-collapsed')));btn.setAttribute('aria-expanded',String(!document.body.classList.contains('menu-collapsed')))}});
 overlay.addEventListener('click',close);closeButton.addEventListener('click',()=>{close();btn.focus()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('menu-open')){close();btn.focus()}if(e.key==='Tab'&&document.body.classList.contains('menu-open')){let nodes=[...document.querySelectorAll('#sidebar button')].filter(x=>x.getClientRects().length),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
 document.addEventListener('click',e=>{if(e.target.closest('#sidebar [data-nav]'))close();let b=e.target.closest('[data-lib-filter],[data-lib-view]');if(b){if(b.dataset.libFilter)libraryFilter=b.dataset.libFilter;if(b.dataset.libView)libraryView=b.dataset.libView;render()}});window.addEventListener('resize',close);close();
}
